import React, { Component } from "react";
import Loader from "react-loader-spinner";
import {
	Card,
	CardBody,
	CardHeader,
	Col,
	Row,
	Table,
	Button,
	// FormGroup,
	// Label,
	Alert,
	// Modal,
	// ModalHeader,
	// ModalBody,
	// ModalFooter,
	// CardGroup,
	// Badge,
} from "reactstrap";
import { connect } from "react-redux";
// import Pagination2 from "react-js-pagination";
// import Widget04 from './Widgets04';

import {
	fetchVisaAcquirerSummary,
	downloadVisaAcquirerCsvSummary,
	fetchVisaAcquirerSummaryStats,
} from "../../../../actions/filesets";

import { FormattedMessage } from "react-intl";

// components
import PostingTable from "../../../../components/PostingTable";
import PostingTableHeader from "../../../../components/PostingTableHeader";

// import AddFileSet from './addFileSet';
// import UpdateFileSet from './updateFileSet';

class UnvalidatedEntries extends Component {
	constructor (props) {
		super(props);
		this.state = {
			modal                         : false,
			showUpdateModal               : false,
			fileSetCreatedAlert           : true,
			filesetUpdatedAlert           : true,
			fileSetDeletedAlert           : true,
			deleteModal                   : false,
			fileSetBatchSummaryErrorAlert : true,
			fileSetT112ErrorAlert         : true,
			activePage                    : 1,
			selectedCode                  : "",
		};
	}
	id = "";
	fileDefinitionId = "";

	static getDerivedStateFromProps (props, state) {
		if (props.fileSets.selectedAffiliateCode !== state.selectedCode) {
			return {
				selectedCode : props.fileSets.selectedAffiliateCode,
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		if (this.state.selectedCode) {
			this.props.fetchVisaAcquirerSummary(this.props.match.params.date, this.state.selectedCode);
			this.props.fetchVisaAcquirerSummaryStats(this.props.match.params.date, this.state.selectedCode);
		}
	}

	componentDidUpdate (prevProps) {
		if (this.props.fileSets) {
			if (this.props.fileSets.selectedAffiliateCode !== prevProps.fileSets.selectedAffiliateCode) {
				this.props.fetchVisaAcquirerSummary(this.props.match.params.date, this.state.selectedCode);
				this.props.fetchVisaAcquirerSummaryStats(this.props.match.params.date, this.state.selectedCode);
			}
		}

		if (this.props.match.params.date !== prevProps.match.params.date) {
			this.props.fetchVisaAcquirerSummary(this.props.match.params.date, this.state.selectedCode);
			this.props.fetchVisaAcquirerSummaryStats(this.props.match.params.date, this.state.selectedCode);
		}
	}

	onSubmit = (values) => {
		this.props.fetchFileSetBatchSummary(
			this.props.match.params.filesetId,
			this.props.match.params.batchesId,
			values.affiliate.value,
		);
	};

	onSubmitUpdate = (values) => {
		this.props.updateFileSet(this.id, values);
		this.closeUpdateModal();
	};

	setUpProduct = (id) => {
		this.props.history.push(`/processors/${id}/subgroups/addProduct`);
	};

	toggle = () => {
		this.props.history.push(`/filesets/${this.props.match.params.id}/definitions/add`);
	};
	closeModal = () => {
		this.setState({ modal: false });
	};

	// componentWillUnmount(){
	//   this.props.subGroupCreated.subGroupCreated = null;
	//   this.props.subGroupCreated.createSubGroupError = null;
	//   this.props.subGroupCreated.updatedSubGroup = null;
	// }

	updateSubGroup = (id) => {
		this.clearNotifications();
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
		this.id = id;
		this.props.fetchFileSet(id);
	};

	closeUpdateModal = () => {
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
	};

	toggleUpdate = () => {
		this.setState({ showUpdateModal: !this.state.showUpdateModal });
	};

	clearNotifications = () => {
		this.props.fileSets.fileSetCreated = null;
		// this.props.subGroupCreated.createSubGroupError = null;
		// this.props.subGroupCreated.subGroupCreated = null;
	};

	onDismissFileSetCreatedSuccessAlert = () => {
		this.setState({
			fileSetCreatedAlert : false,
		});
	};

	onDismissFileSetUpdatedSuccessAlert = () => {
		this.setState({
			fileSetUpdatedAlert : false,
		});
	};

	deleteFileDefinition = (id) => {
		this.clearNotifications();
		this.setState({ deleteModal: true });
		this.fileDefinitionId = id;
	};

	toggleConfirm = () => {
		this.setState({ deleteModal: !this.state.deleteModal });
	};
	confirm = () => {
		this.props.deleteFileSetDefinition(this.props.match.params.id, this.fileDefinitionId);
		this.setState({ deleteModal: false });
	};

	onDismissFileSetDeletedSuccessAlert = () => {
		this.setState({
			fileSetDeletedAlert : false,
		});
	};

	onDismissFileSetBatchSummaryErrorAlert = () => {
		this.setState({
			fileSetBatchSummaryErrorAlert : false,
		});
	};

	downloadFileSetBatchesSummaryCsv = (fileSetId, batchesId, name) => {
		this.props.downloadFileSetBatchesSummaryCsv(fileSetId, batchesId, name);
	};

	onDismissFileSetT112ErrorAlert = () => {
		this.setState({
			fileSetT112ErrorAlert : false,
		});
	};

	downloadVisaPostingSummary = (summaryDate, affiliateCode) => {
		this.setState(
			{
				isLoading : true,
			},
			() => this.props.downloadVisaAcquirerCsvSummary(summaryDate, affiliateCode),
		);
	};

	render () {
		return (
			<div className='animated fadeIn'>
				{this.props.visaAcquirerSummaryError ? (
					<Alert
						color='danger'
						isOpen={this.state.fileSetUpdatedAlert}
						toggle={this.onDismissFileSetUpdatedSuccessAlert}
					>
						{this.props.visaAcquirerSummaryError.data.message}
					</Alert>
				) : null}

				<Row>
					<Col lg={12}>
						{this.props.fileSets.t464SumaryError ? (
							<Alert
								color='danger'
								isOpen={this.state.fileSetT112ErrorAlert}
								toggle={this.onDismissFileSetT112ErrorAlert}
							>
								{this.props.fileSets.t464SumaryError.data.message}
							</Alert>
						) : null}
						<Card>
							<CardHeader>
								<strong>Visa Acquirer {this.props.match.params.date} Summary</strong>
								<div className='card-header-actions'>
									{this.props.fileSets.visaAcquirerSummary ? this.props.fileSets.visaAcquirerSummary
										.data.length > 0 ? (
										<Button
											type='button'
											className={"float-right mb-0 btn-sm mx-1"}
											onClick={(e) =>
												this.downloadVisaPostingSummary(
													this.props.match.params.date,
													this.state.selectedCode,
												)}
											color={"success"}
											download={"" + 1 + ".csv"}
										>
											<span className={"d-flex px-2 justify-content-center align-items-center"}>
												<i className='fa fa-download' />&nbsp;
												{this.props.fileSets.download_status && (
													<Loader
														type='ThreeDots'
														color='#FFF'
														height={30}
														width={30}
														style={{ textAlign: "center" }}
													/>
												)}
												{!this.props.fileSets.download_status && (
													<FormattedMessage id='Download CSV' defaultMessage='Download CSV' />
												)}
											</span>
										</Button>
									) : null : null}
								</div>
							</CardHeader>

							<CardBody>
								{/* Handle loading */}
								{!this.props.visaAcquirerSummaryError &&
								!this.props.visaAcquirerSummary && (
									<article className='d-flex justify-content-center align-items-center'>
										<div>
											<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
										</div>
									</article>
								)}

								{/* Handle 404 not found */}
								{this.props.visaAcquirerSummaryError &&
								!this.props.visaAcquirerSummary && (
									<article className='d-flex justify-content-center align-items-center'>
										<p className='text-center text-danger'>
											<FormattedMessage
												id='There are no fileset batches summary at the moment.'
												defaultMessage='There are no fileset batches summary at the moment.'
											/>
										</p>
									</article>
								)}

								{/* Handle display content */}
								{this.props.visaAcquirerSummary && (
									<Table hover bordered striped responsive size='sm' style={{ minWidth: "180%" }}>
										<thead>
											<PostingTableHeader />
										</thead>
										<tbody>
											<PostingTable dataRecords={[ ...this.props.visaAcquirerSummary.data ]} />
										</tbody>
									</Table>
								)}

								{/* {this.props.fileSets.fileSetBatchesPaginated?<nav>
                    <Pagination2
                        activePage={this.state.activePage}
                        itemsCountPerPage={20}
                        totalItemsCount={this.props.fileSets.fileSetBatchesPaginated?this.props.fileSets.fileSetBatchesPaginated.meta.totalElements:null}
                        pageRangeDisplayed={5} 
                        onChange={this.handlePageChange}
                    />
                    </nav>:'' } */}
							</CardBody>
						</Card>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		visaAcquirerSummary      : state.fileSets.visaAcquirerSummary,
		visaAcquirerSummaryError : state.fileSets.visaAcquirerSummaryError,
		fileSets                 : state.fileSets,
		utils                    : state.utils,
	};
};

export default connect(mapStateToProps, {
	fetchVisaAcquirerSummary,
	downloadVisaAcquirerCsvSummary,
	fetchVisaAcquirerSummaryStats,
})(UnvalidatedEntries);
